import{_ as t,a0 as p,w as d,s as o,ao as c,I as l,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 终端上使用行编辑器 ed | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 终端上使用行编辑器 ed | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 终端上使用行编辑器 ed | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 终端上使用行编辑器 ed | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20201212 Power up your Linux terminal text editor with ed","title":"在 Linux 终端上使用行编辑器 ed","tag":"202204","desc":""},"relativePath":"202204/20201212 Power up your Linux terminal text editor with ed.md","filePath":"[post].md"}'),h={name:"202204/20201212 Power up your Linux terminal text editor with ed.md"};function r(g,s,u,k,b,m){const a=p("Link");return d(),o("div",null,[s[15]||(s[15]=c(`<h1 id="在-linux-终端上使用行编辑器-ed" tabindex="-1">在 Linux 终端上使用行编辑器 ed <a class="header-anchor" href="#在-linux-终端上使用行编辑器-ed" aria-label="Permalink to “在 Linux 终端上使用行编辑器 ed”">​</a></h1><blockquote><p>这个看似简单的编辑器为用户提供了许多易于学习和使用的命令。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202204/04/145334l9w92ngiccginicn.jpg" alt=""></p><p>GNU <code>ed</code> 命令是一个行编辑器。它被认为是标准的 Unix 文本编辑器，因为它是首个出现在 Unix 的文本编辑器，并且它曾经无处不在，你在任何一个 POSIX 系统中都能找到它（通常来说，你现在也可以）。在某种程度上，你可以很容易看出来它是第一个文本编辑器，因为它在许多方面的功能都十分基础。和其他大多数的文本编辑器不同，它不会打开一个属于自己的窗口或显示区域，事实上，在默认情况下，它甚至不会提示用户输入文字。从另一个方面来说，它在交互功能上的缺失也可以成为一个优点。它是一个多功能的编辑器，你可以用简短的命令控制它，无论是在交互式的命令行中，还是在编写的 shell 脚本里。</p><h3 id="安装-ed" tabindex="-1">安装 ed <a class="header-anchor" href="#安装-ed" aria-label="Permalink to “安装 ed”">​</a></h3><p>如果你正在使用 Linux 或者 BSD 的话，你很可能已经默认安装了 <code>ed</code>（在 Linux 上是 GNU 版 <code>ed</code>，而在 BSD 上是 BSD 版 <code>ed</code>）。但是，一些极简的环境可能没有包括 <code>ed</code>，这也没关系，你的发行版的软件仓库中很可能有 <code>ed</code> 可供下载。macOS 默认安装了 BSD 版 <code>ed</code>。</p><h3 id="启动-ed" tabindex="-1">启动 ed <a class="header-anchor" href="#启动-ed" aria-label="Permalink to “启动 ed”">​</a></h3><p>当你启动 <code>ed</code> 的时候，你的终端提示符不见了，看起来好像是 <code>ed</code> 停止运行了。其实它没有，它只是在等待你输入指令而已。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed</span></span></code></pre></div><p>为使 <code>ed</code> 显示更详细的信息，你可以输入命令 <code>p</code> 让它返回一个提示符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed</span></span>
<span class="line"><span>p</span></span>
<span class="line"><span>?</span></span></code></pre></div><p>这个问号（<code>?</code>）是默认的 <code>ed</code> 提示符。</p><h3 id="缓冲区" tabindex="-1">缓冲区 <a class="header-anchor" href="#缓冲区" aria-label="Permalink to “缓冲区”">​</a></h3><p>当 <code>ed</code> 激活时，你其实是在和一个叫 <ruby>缓冲区<rt>buffer</rt></ruby> 的东西打交道。缓冲区是内存中的一块区域。你并不会直接编辑文件，而是在编辑它对应的缓冲区。当你退出 <code>ed</code> 却没有把修改保存到磁盘的文件上时，所有的修改都会丢失，因为它们只在缓冲区里存在。（这对于一个已经习惯了初始的 <ruby>草图缓冲区<rt>scratch buffer</rt></ruby> 的资深 Emacs 用户可能很耳熟。）</p><h3 id="使用-ed-输入文本" tabindex="-1">使用 ed 输入文本 <a class="header-anchor" href="#使用-ed-输入文本" aria-label="Permalink to “使用 ed 输入文本”">​</a></h3><p>启动 <code>ed</code> 后，你处于命令模式。这意味着你可以向编辑器发送指令，比如让它显示一个提示符，而不是空白区域。你可以使用 <code>a</code> 命令开始附加文本到当前的缓冲区，使用一个实心的点 <code>.</code> 来终止输入。比如，下面的这个例子往缓冲区里附加了两行文字（“hello world” 和 “hello ed”）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>a</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>hello ed</span></span>
<span class="line"><span>.</span></span></code></pre></div><p>使用点 <code>.</code> 终止输入后，你将回到命令模式。</p><h3 id="查看缓冲区" tabindex="-1">查看缓冲区 <a class="header-anchor" href="#查看缓冲区" aria-label="Permalink to “查看缓冲区”">​</a></h3><p>怎样查看当前缓冲区里都有什么呢？你可以输入想要查看的行号，也可以使用 <code>,p</code> 命令来显示所有的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>hello ed</span></span>
<span class="line"><span>,p</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>hello ed</span></span></code></pre></div><h3 id="写入文件" tabindex="-1">写入文件 <a class="header-anchor" href="#写入文件" aria-label="Permalink to “写入文件”">​</a></h3><p>如果你现在对文本很满意，你可以使用 <code>w</code> 命令把缓冲区写入到文件中，后面跟上目标文件名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>w example.txt</span></span>
<span class="line"><span>19</span></span></code></pre></div><p>写操作后显示的那个数字代表着写入到文件中的字符数。</p><h3 id="读取文件" tabindex="-1">读取文件 <a class="header-anchor" href="#读取文件" aria-label="Permalink to “读取文件”">​</a></h3><p>除了使用 <code>ed</code> 来读取文本，你也可以使用 <code>r</code> 命令把一个已经存在的文件加载到到缓冲区里：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>r myfile.txt</span></span></code></pre></div><p>另外，你也可以在启动 <code>ed</code> 时，在它后面加上你想要加载到缓冲区里的文件名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed myfile.txt</span></span></code></pre></div><h3 id="编辑缓冲区" tabindex="-1">编辑缓冲区 <a class="header-anchor" href="#编辑缓冲区" aria-label="Permalink to “编辑缓冲区”">​</a></h3><p>鉴于 <code>ed</code> 是一个文本编辑器，你当然可以使用一种特殊的语法来编辑缓冲区里的文本。使用 <code>sed</code> 或 <code>vim</code> 的用户或许会觉得这个语法很熟悉。假设现在缓冲区里已经加载了一个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed myfile.txt</span></span>
<span class="line"><span>,p</span></span>
<span class="line"><span>This is an example document.</span></span>
<span class="line"><span>There is some text, but not much.</span></span>
<span class="line"><span>There is some errors, but not much.</span></span></code></pre></div><p>如果你要把第一句话中的 <code>document</code> 修改为 <code>file</code>，你可以先选择目标行（<code>1</code>），然后使用 <code>s</code> 命令调用搜索函数，后面跟着搜索文本和替换文本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>This is an example document.</span></span>
<span class="line"><span>s/document/file/</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>This is an example file.</span></span></code></pre></div><p>如果你要编辑其他行，步骤也是一样的，只需提供一个不同的行号即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>There is some errors, but not much.</span></span>
<span class="line"><span>s/is/are/</span></span>
<span class="line"><span>s/much/many/</span></span></code></pre></div><p>你可以使用 <code>,p</code> 命令来看到你对缓冲区的历史编辑记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This is an example file.</span></span>
<span class="line"><span>There is some text, but not much.</span></span>
<span class="line"><span>There are some errors, but not many.</span></span></code></pre></div><p>当然，这些修改只存在于缓冲区里。你如果在 <code>ed</code> 编辑器外查看这个文件，你只会看到原始的文本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myfile.txt</span></span>
<span class="line"><span>This is an example document.</span></span>
<span class="line"><span>There is some text, but not much.</span></span>
<span class="line"><span>There is some errors, but not much.</span></span></code></pre></div><p>如果你要把这些修改保存回文件中，使用 <code>w</code> 命令即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>w myfile.txt</span></span>
<span class="line"><span>258</span></span></code></pre></div><h3 id="清空缓冲区" tabindex="-1">清空缓冲区 <a class="header-anchor" href="#清空缓冲区" aria-label="Permalink to “清空缓冲区”">​</a></h3><p>如果想要得到一个新的缓冲区，以此来打开一个新的文件，或者把一个新的文件加载到不同的环境中，你可以使用 <code>c</code> 命令。使用这个清空缓冲区后，什么也不会输出，因为缓冲已经是空的了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c</span></span>
<span class="line"><span>,p</span></span></code></pre></div><h3 id="退出" tabindex="-1">退出 <a class="header-anchor" href="#退出" aria-label="Permalink to “退出”">​</a></h3><p>如果要退出当前的 <code>ed</code> 会话，你可以使用 <code>q</code> 命令。它并不会给你一个保存缓冲区的机会，所以你要确保自己在这之前执行了保存操作。</p><h3 id="尝试一下-ed-吧" tabindex="-1">尝试一下 ed 吧 <a class="header-anchor" href="#尝试一下-ed-吧" aria-label="Permalink to “尝试一下 ed 吧”">​</a></h3><p><code>ed</code> 还可以做到很多事情，学习 <code>ed</code> 可以让你知道它和部分的 <code>vim</code> 是如何工作的。我并没有尝试使用 <code>ed</code> 来写这篇文章，老实说，我也不认为它是通常意义上的最佳文本编辑器。但是，<code>ed</code> 仍然是一个出色的编辑器。通过阅读它的文档，你可以很轻松地学会它。在 GNU 系统上，你可以使用 <code>info ed</code> 来查看它的操作手册。</p><hr>`,51)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/20/12/gnu-ed"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/20/12/gnu-ed",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[2]||(s[2]=[e("Seth Kenlon",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),n(a,{href:"https://github.com/lkxed"},{default:i(()=>[...s[4]||(s[4]=[e("lkxed",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=t(h,[["render",r]]);export{y as __pageData,C as default};
